import sys

def eval_rpn(tokens):
    stack = []
    for t in tokens:
        if t in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if t == '+': stack.append(a + b)
            elif t == '-': stack.append(a - b)
            elif t == '*': stack.append(a * b)
            elif t == '/': stack.append(int(a / b))
        else:
            stack.append(int(t))
    return stack[0]

def main():
    data = sys.stdin.read().split()
    if not data: return
    n = int(data[0])
    tokens = data[1:1+n]
    print(eval_rpn(tokens))

if __name__ == '__main__':
    main()

