from collections import deque

def max_sliding_window(n, k, nums):
    q = deque()
    res = []
    for i, num in enumerate(nums):
        if q and q[0] < i - k + 1:
            q.popleft()
        while q and nums[q[-1]] < num:
            q.pop()
        q.append(i)
        if i >= k - 1:
            res.append(nums[q[0]])
    return res

