string decodeString(string s) {
    stack<int> numSt;
    stack<string> strSt;
    string cur = "";
    int k = 0;
    for (char c : s) {
        if (isdigit(c)) {
            k = k * 10 + (c - '0');
        } else if (c == '[') {
            numSt.push(k);
            strSt.push(cur);
            k = 0;
            cur = "";
        } else if (c == ']') {
            int repeat = numSt.top(); numSt.pop();
            string prev = strSt.top(); strSt.pop();
            string temp = "";
            while (repeat--) temp += cur;
            cur = prev + temp;
        } else {
            cur += c;
        }
    }
    return cur;
}

