            strcpy(stack_str[top], "");
            k = 0;
        } else if (c == ']') {
            int rep = stack_num[top - 1];
            char temp[5000];
            strcpy(temp, stack_str[top]);
            top--;
            for (int r = 0; r < rep; r++) {
                strcat(stack_str[top], temp);
            }
