import sys

def ship_within_days(n, days, weights):
    l, r = max(weights), sum(weights)
    ans = r
    while l <= r:
        mid = (l + r) // 2
        d_needed = 1
        cur_w = 0
        for w in weights:
            if cur_w + w > mid:
                d_needed += 1
                cur_w = w
            else:
                cur_w += w
        if d_needed <= days:
            ans = mid
            r = mid - 1
        else:
            l = mid + 1
    return ans

