#include <stdio.h>
#include <stdlib.h>

typedef struct { int val, cnt; } Item;
int cmpCnt(const void *a, const void *b) { return (((Item*)b)->cnt - ((Item*)a)->cnt); }
int cmpVal(const void *a, const void *b) { return (*(int*)a - *(int*)b); }

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    int *nums = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &nums[i]);
    // Simple frequency count
    Item items[1000];
    int item_count = 0;
    for (int i = 0; i < n; i++) {
        int found = 0;
        for (int j = 0; j < item_count; j++) {
            if (items[j].val == nums[i]) { items[j].cnt++; found = 1; break; }
        }
        if (!found) {
            items[item_count].val = nums[i];
            items[item_count].cnt = 1;
            item_count++;
        }
    }
    qsort(items, item_count, sizeof(Item), cmpCnt);
    int *res = (int*)malloc(k * sizeof(int));
    for (int i = 0; i < k; i++) res[i] = items[i].val;
    qsort(res, k, sizeof(int), cmpVal);
    for (int i = 0; i < k; i++) printf("%d%s", res[i], (i == k - 1 ? "" : " "));
    printf("\n");
    free(nums); free(res);
    return 0;
}

