import sys

def num_islands(m, n, grid):
    visited = [[False] * n for _ in range(m)]
    count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1' and not visited[i][j]:
                count += 1
                # DFS
                stack = [(i, j)]
                visited[i][j] = True
                while stack:
                    r, c = stack.pop()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == '1' and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
    return count

def main():
    lines = sys.stdin.read().split()
    if not lines: return
    m, n = int(lines[0]), int(lines[1])
    grid = lines[2:2+m]
    print(num_islands(m, n, grid))

if __name__ == '__main__':
    main()

