    int edges_u[5005], edges_v[5005];
    for (int i = 0; i < p; i++) {
        scanf("%d %d", &edges_u[i], &edges_v[i]);
        inDeg[edges_u[i]]++;
    }
    int q[2005], head = 0, tail = 0;
    for (int i = 0; i < n; i++) if (inDeg[i] == 0) q[tail++] = i;
    int visited = 0;
    while (head < tail) {
        int node = q[head++];
        visited++;
        for (int i = 0; i < p; i++) {
            if (edges_v[i] == node) {
                inDeg[edges_u[i]]--;
                if (inDeg[edges_u[i]] == 0) q[tail++] = edges_u[i];
            }
        }
    }
    printf("%s\n", visited == n ? "true" : "false");
    return 0;
}

