#include <stdlib.h>

int lowerBound(int *tails, int size, int x) {
    int l = 0, r = size;
    while (l < r) {
        int mid = (l + r) / 2;
        if (tails[mid] >= x) r = mid;
        else l = mid + 1;
    }
    return l;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int *nums = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &nums[i]);
    int *tails = (int*)malloc(n * sizeof(int));
    int len = 0;
    for (int i = 0; i < n; i++) {
        int idx = lowerBound(tails, len, nums[i]);
        if (idx == len) tails[len++] = nums[i];
        else tails[idx] = nums[i];
    }
    printf("%d\n", len);
    free(nums); free(tails);
    return 0;
}

