typedef struct { int s, e; } Interval;

int cmp(const void* a, const void* b) {
    Interval* ia = (Interval*)a;
    Interval* ib = (Interval*)b;
    return ia->s - ib->s;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    Interval *arr = (Interval*)malloc(n * sizeof(Interval));
    for (int i=0; i<n; i++) scanf("%d %d", &arr[i].s, &arr[i].e);
    qsort(arr, n, sizeof(Interval), cmp);
    Interval *res = (Interval*)malloc(n * sizeof(Interval));
    int rcount = 0;
    for (int i=0; i<n; i++) {
        if (rcount == 0 || res[rcount-1].e < arr[i].s) {
            res[rcount++] = arr[i];
        } else {
            if (arr[i].e > res[rcount-1].e) res[rcount-1].e = arr[i].e;
        }
    }
    for (int i=0; i<rcount; i++) printf("%d %d\n", res[i].s, res[i].e);
    free(arr);
    free(res);
    return 0;
}

