import sys
from collections import deque

def oranges_rotting(grid, m, n):
    q = deque()
    fresh = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2: q.append((i, j, 0))
            elif grid[i][j] == 1: fresh += 1
    minutes = 0
    while q:
        r, c, d = q.popleft()
        minutes = max(minutes, d)
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 1:
                grid[nr][nc] = 2
                fresh -= 1
                q.append((nr, nc, d + 1))
    return -1 if fresh > 0 else minutes

def main():
    data = sys.stdin.read().split()
    if not data: return
    m, n = int(data[0]), int(data[1])
    grid = []
    idx = 2
    for _ in range(m):
        grid.append([int(x) for x in data[idx:idx+n]])
        idx += n
    print(oranges_rotting(grid, m, n))

if __name__ == '__main__':
    main()

