        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int r = curr[0], c = curr[1], d = curr[2];
            mins = Math.max(mins, d);
            for (int[] dir : dirs) {
                int nr = r + dir[0], nc = c + dir[1];
                if (nr>=0 && nr<m && nc>=0 && nc<n && grid[nr][nc] == 1) {
                    grid[nr][nc] = 2;
                    fresh--;
                    q.add(new int[]{nr, nc, d + 1});
                }
            }
        }
