import sys

def combination_sum_count(candidates, target):
    count = 0
    def backtrack(idx, rem):
        nonlocal count
        if rem == 0:
            count += 1
            return
        if rem < 0:
            return
        for i in range(idx, len(candidates)):
            backtrack(i, rem - candidates[i])
    backtrack(0, target)
    return count

