def calculate(s):
    stack = []
    curr = 0
    op = '+'
    s = s.strip() + '+'
    for c in s:
        if c == ' ': continue
        if c.isdigit():
            curr = curr * 10 + int(c)
        else:
            if op == '+': stack.append(curr)
            elif op == '-': stack.append(-curr)
            elif op == '*': stack.append(stack.pop() * curr)
            elif op == '/': stack.append(int(stack.pop() / curr))
            op = c
            curr = 0
    return sum(stack)

