import sys

def has_path_sum(target_sum, vals):
    if not vals or vals[0] == 'null': return False
    class Node:
        def __init__(self, val): self.val = val; self.left = None; self.right = None
    root = Node(int(vals[0]))
    q = [root]
    i = 1
    while i < len(vals) and q:
        curr = q.pop(0)
        if i < len(vals) and vals[i] != 'null':
            curr.left = Node(int(vals[i]))
            q.append(curr.left)
        i += 1
        if i < len(vals) and vals[i] != 'null':
            curr.right = Node(int(vals[i]))
            q.append(curr.right)
        i += 1
    def dfs(node, rem):
        if not node: return False
        if not node.left and not node.right: return rem == node.val
        return dfs(node.left, rem - node.val) or dfs(node.right, rem - node.val)
    return dfs(root, target_sum)

def main():
    data = sys.stdin.read().split()
    if not data: return
    target = int(data[0])
    vals = data[1:]
    print('true' if has_path_sum(target, vals) else 'false')

if __name__ == '__main__':
    main()

