import java.util.*;

public class Main {
    static class Node { int val; Node left, right; Node(int v){val=v;} }
    static boolean dfs(Node node, int rem) {
        if (node == null) return false;
        if (node.left == null && node.right == null) return rem == node.val;
        return dfs(node.left, rem - node.val) || dfs(node.right, rem - node.val);
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int target = sc.nextInt();
        List<String> list = new ArrayList<>();
        while (sc.hasNext()) list.add(sc.next());
        if (list.isEmpty() || list.get(0).equals("null")) { System.out.println("false"); return; }
        Node root = new Node(Integer.parseInt(list.get(0)));
        Queue<Node> q = new LinkedList<>();
        q.add(root);
        int i = 1;
        while (i < list.size() && !q.isEmpty()) {
            Node curr = q.poll();
            if (i < list.size() && !list.get(i).equals("null")) {
                curr.left = new Node(Integer.parseInt(list.get(i)));
                q.add(curr.left);
            }
            i++;
            if (i < list.size() && !list.get(i).equals("null")) {
                curr.right = new Node(Integer.parseInt(list.get(i)));
                q.add(curr.right);
            }
            i++;
        }
        System.out.println(dfs(root, target) ? "true" : "false");
    }
}

