        if (!sc.hasNext()) return;
        String begin = sc.next(), end = sc.next();
        int n = sc.nextInt();
        Set<String> set = new HashSet<>();
        for (int i=0; i<n; i++) set.add(sc.next());
        if (!set.contains(end) && !begin.equals(end)) { System.out.println(0); return; }
        if (begin.equals(end)) { System.out.println(1); return; }
        Queue<String> q = new LinkedList<>();
        q.add(begin);
        Set<String> visited = new HashSet<>();
        visited.add(begin);
        int steps = 1;
        while (!q.isEmpty()) {
            int size = q.size();
            for (int k=0; k<size; k++) {
                String curr = q.poll();
                if (curr.equals(end)) { System.out.println(steps); return; }
                char[] chs = curr.toCharArray();
                for (int i=0; i<chs.length; i++) {
                    char old = chs[i];
                    for (char c='a'; c<='z'; c++) {
                        chs[i] = c;
                        String nxt = new String(chs);
                        if (set.contains(nxt) && visited.add(nxt)) q.add(nxt);
                    }
                    chs[i] = old;
                }
            }
            steps++;
        }
        System.out.println(0);
    }
