    for (int i=0; i<n; i++) { string w; cin >> w; set.insert(w); }
    if (!set.count(end) && begin != end) { cout << 0 << "\n"; return 0; }
    if (begin == end) { cout << 1 << "\n"; return 0; }
    queue<pair<string, int>> q;
    unordered_set<string> visited;
    q.push({begin, 1}); visited.insert(begin);
    while (!q.empty()) {
        auto [word, steps] = q.front(); q.pop();
        if (word == end) { cout << steps << "\n"; return 0; }
        for (int i=0; i<(int)word.size(); i++) {
            char old = word[i];
            for (char c='a'; c<='z'; c++) {
                word[i] = c;
                if (set.count(word) && visited.insert(word).second) {
                    q.push({word, steps + 1});
                }
            }
            word[i] = old;
        }
    }
    cout << 0 << "\n";
    return 0;
}

