import sys

def longest_increasing_path(matrix, m, n):
    memo = {}
    def dfs(r, c):
        if (r, c) in memo: return memo[(r, c)]
        val = matrix[r][c]
        res = 1
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and matrix[nr][nc] > val:
                res = max(res, 1 + dfs(nr, nc))
        memo[(r, c)] = res
        return res
    ans = 0
    for i in range(m):
        for j in range(n):
            ans = max(ans, dfs(i, j))
    return ans

def main():
    data = sys.stdin.read().split()
    if not data: return
    m, n = int(data[0]), int(data[1])
    matrix = []
    idx = 2
    for _ in range(m):
        matrix.append([int(x) for x in data[idx:idx+n]])
        idx += n
    print(longest_increasing_path(matrix, m, n))

if __name__ == '__main__':
    main()

