import sys

def find_redundant_connection(edges, n):
    parent = list(range(n + 1))
    def find(x):
        if parent[x] != x: parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        px, py = find(x), find(y)
        if px == py: return False
        parent[px] = py
        return True
    for u, v in edges:
        if not union(u, v):
            return [u, v]
    return []

def main():
    data = sys.stdin.read().split()
    if not data: return
    n = int(data[0])
    edges = []
    idx = 1
    for _ in range(n):
        edges.append((int(data[idx]), int(data[idx+1])))
        idx += 2
    ans = find_redundant_connection(edges, n)
    print(f'{ans[0]} {ans[1]}')

if __name__ == '__main__':
