#include <stdio.h>
#include <stdlib.h>

void swap(int* a, int* b) { int t = *a; *a = *b; *b = t; }
void min_heapify(int h[], int n, int i) {
    int smallest = i, l = 2*i+1, r = 2*i+2;
    if (l < n && h[l] < h[smallest]) smallest = l;
    if (r < n && h[r] < h[smallest]) smallest = r;
    if (smallest != i) {
        swap(&h[i], &h[smallest]);
        min_heapify(h, n, smallest);
    }
}
int pop(int h[], int* n) {
    int root = h[0];
    h[0] = h[--(*n)];
    min_heapify(h, *n, 0);
    return root;
}
void push(int h[], int* n, int val) {
    int i = (*n)++;
    h[i] = val;
    while (i != 0 && h[(i-1)/2] > h[i]) {
        swap(&h[i], &h[(i-1)/2]);
        i = (i-1)/2;
    }
}
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int h[10005]; int hSize = 0;
    for (int i=0; i<n; i++) { int x; scanf("%d", &x); push(h, &hSize, x); }
    int total = 0;
    while (hSize > 1) {
        int x = pop(h, &hSize);
        int y = pop(h, &hSize);
        total += (x + y);
        push(h, &hSize, x + y);
    }
    printf("%d\n", total);
    return 0;
}

