    static class Node { int val; Node left, right; Node(int v){val=v;} }
    static class Pair { Node node; long idx; Pair(Node n, long i){node=n; idx=i;} }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        List<String> list = new ArrayList<>();
        while (sc.hasNext()) list.add(sc.next());
        if (list.isEmpty() || list.get(0).equals("null")) { System.out.println(0); return; }
        Node root = new Node(Integer.parseInt(list.get(0)));
        Queue<Node> q = new LinkedList<>();
        q.add(root);
        int i = 1;
        while (i < list.size() && !q.isEmpty()) {
            Node curr = q.poll();
            if (i < list.size() && !list.get(i).equals("null")) {
                curr.left = new Node(Integer.parseInt(list.get(i)));
                q.add(curr.left);
            }
            i++;
            if (i < list.size() && !list.get(i).equals("null")) {
                curr.right = new Node(Integer.parseInt(list.get(i)));
                q.add(curr.right);
            }
            i++;
        }
        long maxW = 0;
        Queue<Pair> dq = new LinkedList<>();
        dq.add(new Pair(root, 0));
        while (!dq.isEmpty()) {
            int size = dq.size();
            long first = 0, last = 0;
            for (int k=0; k<size; k++) {
                Pair p = dq.poll();
                if (k == 0) first = p.idx;
                if (k == size - 1) last = p.idx;
                if (p.node.left != null) dq.add(new Pair(p.node.left, 2 * (p.idx - first)));
                if (p.node.right != null) dq.add(new Pair(p.node.right, 2 * (p.idx - first) + 1));
            }
            maxW = Math.max(maxW, last - first + 1);
        }
        System.out.println(maxW);
    }
}

