import sys

def findPeak(arr):
    l, r = 0, len(arr) - 1
    while l < r:
        mid = (l + r) // 2
        if arr[mid] < arr[mid + 1]: l = mid + 1
        else: r = mid
    return l

def binSearch(arr, target, l, r, asc):
    while l <= r:
        mid = (l + r) // 2
        if arr[mid] == target: return mid
        if asc:
            if arr[mid] < target: l = mid + 1
            else: r = mid - 1
        else:
            if arr[mid] < target: r = mid - 1
            else: l = mid + 1
    return -1

def main():
    data = sys.stdin.read().split()
    if not data: return
    target = int(data[0])
    n = int(data[1])
    arr = [int(x) for x in data[2:2+n]]
    peak = findPeak(arr)
    idx = binSearch(arr, target, 0, peak, True)
    if idx != -1: print(idx)
    else: print(binSearch(arr, target, peak + 1, n - 1, False))

if __name__ == '__main__':
    main()

