public class Main {
    static class Pair {
        int val, idx;
        Pair(int v, int i) { val = v; idx = i; }
    }
    static void mergeSort(Pair[] arr, int l, int r, int[] res, Pair[] temp) {
        if (l >= r) return;
        int mid = (l + r) / 2;
        mergeSort(arr, l, mid, res, temp);
        mergeSort(arr, mid + 1, r, res, temp);
        int i = l, j = mid + 1, k = l;
        while (i <= mid && j <= r) {
            if (arr[i].val <= arr[j].val) {
                res[arr[i].idx] += j - (mid + 1);
                temp[k++] = arr[i++];
            } else {
                temp[k++] = arr[j++];
            }
        }
        while (i <= mid) {
            res[arr[i].idx] += j - (mid + 1);
            temp[k++] = arr[i++];
        }
        while (j <= r) temp[k++] = arr[j++];
        for (int p=l; p<=r; p++) arr[p] = temp[p];
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        Pair[] arr = new Pair[n];
        for (int i=0; i<n; i++) arr[i] = new Pair(sc.nextInt(), i);
        int[] res = new int[n];
        Pair[] temp = new Pair[n];
        mergeSort(arr, 0, n - 1, res, temp);
        StringBuilder sb = new StringBuilder();
        for (int i=0; i<n; i++) sb.append(res[i]).append(i == n-1 ? "" : " ");
        System.out.println(sb.toString());
    }
}

