#include <stdlib.h>

typedef struct { int val, idx; } Pair;

void mergeSort(Pair* arr, int l, int r, int* res, Pair* temp) {
    if (l >= r) return;
    int mid = (l + r) / 2;
    mergeSort(arr, l, mid, res, temp);
    mergeSort(arr, mid + 1, r, res, temp);
    int i = l, j = mid + 1, k = l;
    while (i <= mid && j <= r) {
        if (arr[i].val <= arr[j].val) {
            res[arr[i].idx] += j - (mid + 1);
            temp[k++] = arr[i++];
        } else {
            temp[k++] = arr[j++];
        }
    }
    while (i <= mid) {
        res[arr[i].idx] += j - (mid + 1);
        temp[k++] = arr[i++];
    }
    while (j <= r) temp[k++] = arr[j++];
    for (int p=l; p<=r; p++) arr[p] = temp[p];
}

int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    Pair* arr = (Pair*)malloc(n * sizeof(Pair));
    for (int i=0; i<n; i++) { scanf("%d", &arr[i].val); arr[i].idx = i; }
    int* res = (int*)calloc(n, sizeof(int));
    Pair* temp = (Pair*)malloc(n * sizeof(Pair));
    mergeSort(arr, 0, n - 1, res, temp);
    for (int i=0; i<n; i++) printf("%d%s", res[i], i == n-1 ? "" : " ");
    printf("\n");
    free(arr); free(res); free(temp);
    return 0;
}
